const e="kcym-kothamangalam-arangu-kalolsavam",u=2025,t="Read all 27 pages of the Arangu-2025 by-law (Malayalam; text extracted and checked against page renders where a word was unclear). The registration, fee, deadline, contact and date facts are for the 2025 edition and are kept as Variables. The by-law prints no refund rule for the registration fee, no age-wise groups other than the 15 to 30 range, and no marks for the Quiz. It names the Arangu writing (Rachana) competitions but gives no rules for them. It says the venue is Nirmala College, Muvattupuzha, with no street address. The by-law prints the Debate and Quiz on 24 August and all other competitions on 13 September. The contacts printed on p.27 are the diocese office and three office bearers.",n={Title:"Rules & Criteria",Subtitle:"Arangu-2025, the Yuvadeepthi KCYM Kothamangalam Eparchy Kalolsavam. Read these rules before you register.",NoticeTitle:"Please Read Before Registering",Notice:"Registration opens on {{RegistrationStart}} and closes on {{RegistrationDeadline}}. The Debate and Quiz are on {{DebateQuizDate}}. All other competitions are on {{KalolsavamDate}} at {{Venue}}. The registration fee is {{RegistrationFee}}.",Notes:["Only KCYM members aged 15 to 30 can take part.","The unit manager is the only person who contacts the office about the Kalolsavam.","Report at the stage half an hour before your competition and take your chest number."],Sections:[{Key:"general",Title:"About Arangu-2025",Items:["Arangu-2025 is the diocesan Kalolsavam organised by Yuvadeepthi KCYM Kothamangalam Eparchy. This by-law gives the competitions, the conditions and the instructions. All competition arrangements follow this by-law only.","KCYM is the Kerala Christian moral youth movement. As a Catholic organisation, discipline must be kept in the competitions and on the stage. Participants and spectators must strictly keep discipline.","The diocesan committee has full charge of running the diocesan competitions.","The Kalolsavam follows the green code of conduct completely.","The detailed time table of the competitions is published after the registration is complete."]},{Key:"eligibility",Title:"Eligibility",Items:["Only young men and women who are KCYM members and aged 15 to 30 can take part. {{BirthDateRange}}.","Those who accompany a performance (background) in the items where accompaniment is allowed must also be KCYM members.","In individual items, the competition is held separately for men and women. One young man and one young woman from a unit can take part in each individual item.","In group items, only one team from a unit can take part.","One person can take part in 3 individual items and 2 group items.","Parichamuttu Kali is for boys only.","Every participant must carry a certificate with their photo, name details and ID proof, in the form given by the diocese and signed by the Unit Director, on the competition day.","Participants must know the KCYM rules and the discipline they must keep.","Each unit has one unit manager. For the Arangu writing competition, the person chosen with the permission of the Unit Director is also the unit manager of the Kalolsavam. Only the unit manager can contact the office about matters of the Kalolsavam."]},{Key:"registration",Title:"How to Register",Items:["Registration of the competitions opens on {{RegistrationStart}}. The last date to register is {{RegistrationDeadline}}.","Units must complete the registration on the dates given by the diocesan committee.","The registration fee is {{RegistrationFee}}. At registration, upload a screenshot of the online payment of the fee.","At registration, give the names of the participants in individual items and the name of the group leader in group items.","A unit can register for the green room by paying the caution deposit through the Google form given before the competition.","Read the time limit, the number of persons and the judging criteria of each group item carefully before you take part."]},{Key:"fees",Title:"Fees and Fines",Items:["Registration fee: {{RegistrationFee}}.","A fine of {{NoShowFine}} is charged if a unit registers for a group item and does not take part. If the fine is not paid, the unit is disqualified from taking part in the other competitions.","Green room caution deposit: {{GreenRoomDeposit}}. It is returned after the room is checked to be clean. If the room is damaged, the deposit is kept as a fine. If the damage costs more than INR 1000, the unit pays the rest as a fine.","Appeal fee: {{AppealFee}} for each appeal. The fee is not returned if the appeal is not valid."]},{Key:"dates",Title:"Dates",Items:["Registration opens: {{RegistrationStart}}.","Last date to register: {{RegistrationDeadline}}.","Debate and Quiz: {{DebateQuizDate}}.","Kalolsavam (all other competitions): {{KalolsavamDate}}."]},{Key:"venue",Title:"Venue",Items:["The competitions are at {{Venue}}.","Each competition is held in a fixed auditorium, hall or classroom of the college."]},{Key:"teams",Title:"Entries from a Unit",Items:["In group items, one team from a unit can take part.","In individual items, one young man and one young woman from a unit can take part.","One person can take part in at most 3 individual items and 2 group items.","Team sizes: Margamkali 7 (one sings and 6 dance); Parichamuttu Kali 8 (6 play and 2 sing); Mime 3 to 12; KCYM Anthem 3 to 7; Nadanpattu 3 to 7; Ganamela 6 to 8; Quiz up to 3; Debate 2 (one proposer and one opposer)."]},{Key:"levels",Title:"Qualification",Items:["The team or winner that takes first place with an A grade in an item can take part in the State Kalolsavam.","If the first-place team or person does not take part, the team or person with second place and an A grade gets the chance."]},{Key:"conduct",Title:"Rules for the Competition Day",Items:["Report at the stage of each competition half an hour before, and take the chest number.","The stage managers and team managers must hold a meeting half an hour before the competitions.","The units keep and control the things they bring for a competition, at their own responsibility.","The full responsibility for a team from a unit is with the Unit Director, Animator, Unit Manager and unit office bearers. At least one of them must be present for the whole Kalolsavam.","Units that hold the everrolling trophy must bring the trophies to the diocese office before the date set by the diocesan committee.","Do not dump or leave food, plastic, paper or other waste in the college compound. Those who use the washrooms (ladies and gents) must not leave cleaning paper, soap or any other thing there. Everyone must try to keep the college campus clean.","Do not leave food waste or make-up items in the green rooms.","Anyone who causes any conflict on the competition days or damages the property of the institution is fully responsible, with the unit. The persons or the unit are disqualified and fined according to the damage.","Contestants must not ask the judges any doubt about the result or any other matter directly.","No one may speak to the judges before, during or after a competition without the permission of the diocesan committee. The decision of the judges must be respected.","In disputes in the Kalolsavam, the diocesan committee has the right to take the final decision. Participants and units must accept it.","No competition or result of the Kalolsavam may be taken to court.","After the competitions, no criticism or allegation may be made on social media."]},{Key:"judging",Title:"Grades, Points and Time Limits",Items:["Items that get less than 60 percent marks are not graded. Items that get 60 percent or more are given grade A, B or C.","Grade points: A (more than 80%) 5 points; B (70% to 79%) 3 points; C (60% to 69%) 1 point.","Individual items: first place 5 points, second place 3 points, third place 1 point.","Group items: first place 10 points, second place 7 points, third place 5 points.","The points of the grade and of the place are added to get the total marks of the competition.","The time limit applies to all items, group and single. A warning bell rings one minute before the end of the time.","If a competitor takes more than the given time, marks are cut: up to the first minute 5%; from 1 to 2 minutes 10%; above 2 minutes 15%.","The judging criteria and their percentages are printed for each item and are listed under each competition."]},{Key:"prizes",Title:"Champions and Awards",Items:["The unit with the most points in the written (Rachana) and art competitions is declared the champion of Arangu.","The everrolling trophy and a certificate go only to the Champion, the First Runner-up and the Second Runner-up.","In each competition, the first and second place get a certificate and a medal. The third place gets a certificate."]},{Key:"complaints",Title:"Appeals",Items:["An appeal is possible only for the competitions held offline.","After a competition and before the next one begins, the judges announce the result on the stage. The result of an item becomes official only when it appears on the score board, after any appeal.","Only the chest numbers of the first, second and third places are announced.","An appeal must be made within 10 minutes after the result is announced. Use the given form, pay {{AppealFee}}, and have it signed by the Unit Director, President, Secretary, Animator or Unit Manager. Submit it to the Jury of Appeal of the diocesan committee.","The diocesan Appeal Committee has the KCYM Diocese Director, Assistant Director, Animator, President and General Secretary.","If the appeal is not valid, the fee is not returned.","After an appeal is decided, no new appeal or objection is possible.","When an appeal is considered, only one of the Unit Director, President, Secretary, Animator or Unit Manager, and for an individual item only the participant, or for a group item only the team leader, can enter the office.","If the judges' marks were added wrongly and this changed the result, only those results are announced again.","If the judges' result is correct, the appeal committee only explains the faults of the person or team from the judges' notes.","A unit or person that behaves rudely to the judges, attacks them or offers them anything is disqualified by the decision of the Appeal Committee."]},{Key:"other",Title:"Other Notes",Items:["The by-law mentions an Arangu writing (Rachana) competition, and the writing and art competitions in the championship rule. It prints no rules for them, and this template does not carry them."]}],Documents:[]},a=[{ParticipantType:"Individual",Source:"Arangu-2025 by-law p.4 rules 1.k and 1.l",Sections:{About:null,TimeAndFormat:null,Rules:["Individual items are held separately for men and women.","One young man and one young woman from a unit can take part in an individual item."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Individual items are held separately for men and women.
- One young man and one young woman from a unit can take part in an individual item.`},{ParticipantType:"Team",Source:"Arangu-2025 by-law p.4 rules 1.j, 1.i and 1.o",Sections:{About:null,TimeAndFormat:null,Rules:["Only one team from a unit can take part in a group item.","People in the background (accompaniment) must also be KCYM members.","The group leader's name is given at registration.","A team that wins first place with an A grade can take part in the State Kalolsavam."],Allowed:null,NotAllowed:null,Judging:null,Points:["Group places: first 10 points, second 7 points, third 5 points, added to the grade points."],Notes:null},Markdown:`## Rules
- Only one team from a unit can take part in a group item.
- People in the background (accompaniment) must also be KCYM members.
- The group leader's name is given at registration.
- A team that wins first place with an A grade can take part in the State Kalolsavam.

## Points
- Group places: first 10 points, second 7 points, third 5 points, added to the grade points.`}],o=[{AgeGroup:"Youth Solo",Source:"Arangu-2025 by-law p.13 (individual items) and rules 1.h to 1.l",Sections:{About:["Age 15 to 30. {{BirthDateRange}}.","Individual items: Speech, Light Song, Mimicry, Mono Act, Folk Dance, Photography and Spot Choreography."],TimeAndFormat:null,Rules:null,Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## About this competition
- Age 15 to 30. {{BirthDateRange}}.
- Individual items: Speech, Light Song, Mimicry, Mono Act, Folk Dance, Photography and Spot Choreography.`},{AgeGroup:"Youth Team",Source:"Arangu-2025 by-law p.13 (group items) and rules 1.h to 1.l",Sections:{About:["Age 15 to 30. {{BirthDateRange}}.","Group items: Street Play, Margamkali, Parichamuttu Kali, Mime, Chavittunatakam, KCYM Anthem, Nadanpattu, Ganamela, Debate and Quiz."],TimeAndFormat:null,Rules:null,Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## About this competition
- Age 15 to 30. {{BirthDateRange}}.
- Group items: Street Play, Margamkali, Parichamuttu Kali, Mime, Chavittunatakam, KCYM Anthem, Nadanpattu, Ganamela, Debate and Quiz.`}],i=JSON.parse('[{"Title":"Speech (പ്രസംഗം)","Source":"Arangu-2025 by-law p.15 (1. Speech)","Sections":{"About":null,"TimeAndFormat":["Time: 5 minutes.","Language: Malayalam.","The topic is given 5 minutes before."],"Rules":null,"Allowed":null,"NotAllowed":null,"Judging":["Judging: Ability to speak without stage fright 20%; Clear pronunciation 15%; Correct language 15%; Ideas 20%; Fluency 15%; Suitable voice modulation 15%."],"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Time: 5 minutes.\\n- Language: Malayalam.\\n- The topic is given 5 minutes before.\\n\\n## Judging\\n- Judging: Ability to speak without stage fright 20%; Clear pronunciation 15%; Correct language 15%; Ideas 20%; Fluency 15%; Suitable voice modulation 15%."},{"Title":"Light Song (ലളിതഗാനം)","Source":"Arangu-2025 by-law p.15 (2. Light Song)","Sections":{"About":null,"TimeAndFormat":["Time: 5 minutes."],"Rules":null,"Allowed":null,"NotAllowed":["Film songs and classical songs."],"Judging":["Judging: Voice (shareeram) 20%; Pitch and rhythm (shruti-laya) 20%; Gnanabhavam (feeling of the song) 20%; Tala 20%; Correct lyrics (sahitya shuddhi) 20%."],"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Time: 5 minutes.\\n\\n## Not allowed\\n- Film songs and classical songs.\\n\\n## Judging\\n- Judging: Voice (shareeram) 20%; Pitch and rhythm (shruti-laya) 20%; Gnanabhavam (feeling of the song) 20%; Tala 20%; Correct lyrics (sahitya shuddhi) 20%."},{"Title":"Mimicry (മിമിക്രി)","Source":"Arangu-2025 by-law p.15 (3. Mimicry)","Sections":{"About":null,"TimeAndFormat":["Time: 5 minutes."],"Rules":["The presentation must suit moral values. Insulting and mocking remarks must be avoided."],"Allowed":null,"NotAllowed":null,"Judging":["Judging: Justice to the subject 25%; Skill in imitation 25%; Acting 25%; Absorption in the role (tanmayatvam) 25%."],"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Time: 5 minutes.\\n\\n## Rules\\n- The presentation must suit moral values. Insulting and mocking remarks must be avoided.\\n\\n## Judging\\n- Judging: Justice to the subject 25%; Skill in imitation 25%; Acting 25%; Absorption in the role (tanmayatvam) 25%."},{"Title":"Mono Act (മോണോ ആക്ട്)","Source":"Arangu-2025 by-law p.16 (4. Mono Act)","Sections":{"About":["The performer presents an event or a story and imitates all the characters in form, expression and voice."],"TimeAndFormat":["Time: 5 minutes."],"Rules":["The presentation must support moral values. Insulting remarks must be avoided."],"Allowed":null,"NotAllowed":null,"Judging":["Judging: Clear diction 25%; Expression of the idea 25%; Facial and emotional expression (bhavabhinayam) 25%; Dialogue 25%."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- The performer presents an event or a story and imitates all the characters in form, expression and voice.\\n\\n## Time and format\\n- Time: 5 minutes.\\n\\n## Rules\\n- The presentation must support moral values. Insulting remarks must be avoided.\\n\\n## Judging\\n- Judging: Clear diction 25%; Expression of the idea 25%; Facial and emotional expression (bhavabhinayam) 25%; Dialogue 25%."},{"Title":"Folk Dance (നാടോടി നൃത്തം)","Source":"Arangu-2025 by-law p.16 (5. Folk Dance)","Sections":{"About":null,"TimeAndFormat":["Time: 7 minutes."],"Rules":["The form and costume must suit a folk dance. Luxury must be kept as low as possible, and the folk character must be kept.","The song must be a folk song.","Reduce the number of props. No stage set-up is needed."],"Allowed":["For the background, only a recorded cassette, CD or pen drive."],"NotAllowed":["Film songs."],"Judging":["Judging: Precision of form 20%; Costume 20%; Expression 20%; Tala (rhythm) 20%; Movement 20%."],"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Time: 7 minutes.\\n\\n## Rules\\n- The form and costume must suit a folk dance. Luxury must be kept as low as possible, and the folk character must be kept.\\n- The song must be a folk song.\\n- Reduce the number of props. No stage set-up is needed.\\n\\n## Allowed\\n- For the background, only a recorded cassette, CD or pen drive.\\n\\n## Not allowed\\n- Film songs.\\n\\n## Judging\\n- Judging: Precision of form 20%; Costume 20%; Expression 20%; Tala (rhythm) 20%; Movement 20%."},{"Title":"Photography (ഫോട്ടോഗ്രാഫി)","Source":"Arangu-2025 by-law p.17 (6. Photography)","Sections":{"About":["The participant takes photos on the topic given on the spot at the venue of Arangu and hands them in."],"TimeAndFormat":["Time: 1 hour."],"Rules":["Any type of camera can be used, such as a digital camera or a professional camera.","Only a memory card with no data on it is allowed. The memory card must be shown to the organisers before the competition."],"Allowed":null,"NotAllowed":["Mobile cameras."],"Judging":["Judging: Idea 20%; Content 20%; Sensitivity 20%; Creativity 20%; Composition 20%."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- The participant takes photos on the topic given on the spot at the venue of Arangu and hands them in.\\n\\n## Time and format\\n- Time: 1 hour.\\n\\n## Rules\\n- Any type of camera can be used, such as a digital camera or a professional camera.\\n- Only a memory card with no data on it is allowed. The memory card must be shown to the organisers before the competition.\\n\\n## Not allowed\\n- Mobile cameras.\\n\\n## Judging\\n- Judging: Idea 20%; Content 20%; Sensitivity 20%; Creativity 20%; Composition 20%."},{"Title":"Spot Choreography (സ്പോട്ട് കൊറിയോ)","Source":"Arangu-2025 by-law p.17 (7. Spot Choreography)","Sections":{"About":["The participant makes a choreography for different songs in different styles that are given on the spot."],"TimeAndFormat":["Time: 3 minutes."],"Rules":null,"Allowed":null,"NotAllowed":null,"Judging":["Judging: Precision of form 20%; Step 20%; Expression 20%; Tala (rhythm) 20%; Movement 20%."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- The participant makes a choreography for different songs in different styles that are given on the spot.\\n\\n## Time and format\\n- Time: 3 minutes.\\n\\n## Judging\\n- Judging: Precision of form 20%; Step 20%; Expression 20%; Tala (rhythm) 20%; Movement 20%."},{"Title":"Street Play (തെരുവ് നാടകം)","Source":"Arangu-2025 by-law p.18 (1. Street Play)","Sections":{"About":["The play must be based on a contemporary subject and the study topic of that year.","The theme must not hurt human values, question Christian values or the faith truths of the Catholic Church, or lead to character assassination."],"TimeAndFormat":["Presentation time: 20 minutes.","10 minutes can be used for setting up the scene."],"Rules":["Any type of costume can be used, but no paint of any kind on the face.","The number of people can be fixed according to the story.","The team clears the stage after the competition.","The play must be satire. The team has uniformity in decent costume. Acting, dialogue, direction and music are given importance."],"Allowed":["Only the chenda as a background instrument."],"NotAllowed":["A mic is not given."],"Judging":["Judging: Dialogue and acting 25%; Expression of the idea 25%; Suitability of the costume 25%; Overall presentation 25%."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- The play must be based on a contemporary subject and the study topic of that year.\\n- The theme must not hurt human values, question Christian values or the faith truths of the Catholic Church, or lead to character assassination.\\n\\n## Time and format\\n- Presentation time: 20 minutes.\\n- 10 minutes can be used for setting up the scene.\\n\\n## Rules\\n- Any type of costume can be used, but no paint of any kind on the face.\\n- The number of people can be fixed according to the story.\\n- The team clears the stage after the competition.\\n- The play must be satire. The team has uniformity in decent costume. Acting, dialogue, direction and music are given importance.\\n\\n## Allowed\\n- Only the chenda as a background instrument.\\n\\n## Not allowed\\n- A mic is not given.\\n\\n## Judging\\n- Judging: Dialogue and acting 25%; Expression of the idea 25%; Suitability of the costume 25%; Overall presentation 25%."},{"Title":"Margamkali (മാർഗംകളി)","Source":"Arangu-2025 by-law p.19 (2. Margamkali)","Sections":{"About":null,"TimeAndFormat":["Time: 10 minutes at most."],"Rules":["7 persons: one sings and 6 dance.","A traditional lamp is placed on the stage (the organisers give it).","Traditional costume: chatta, mundu and kavani; the mundu has pleats; a wide cap on the hands; bangles, earrings, velakkathu, kasimala and thala; mehendi on the feet. The hair is tied.","The jewellery must not come off while dancing. The dancers must not use their hands as support."],"Allowed":["Elathalam to keep the rhythm."],"NotAllowed":["Other musical instruments or recorded background."],"Judging":["Judging: Suitability of costume 20%; Devotion (bhakti bhavam) 20%; Step 20%; Tala 20%; Music 20%."],"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Time: 10 minutes at most.\\n\\n## Rules\\n- 7 persons: one sings and 6 dance.\\n- A traditional lamp is placed on the stage (the organisers give it).\\n- Traditional costume: chatta, mundu and kavani; the mundu has pleats; a wide cap on the hands; bangles, earrings, velakkathu, kasimala and thala; mehendi on the feet. The hair is tied.\\n- The jewellery must not come off while dancing. The dancers must not use their hands as support.\\n\\n## Allowed\\n- Elathalam to keep the rhythm.\\n\\n## Not allowed\\n- Other musical instruments or recorded background.\\n\\n## Judging\\n- Judging: Suitability of costume 20%; Devotion (bhakti bhavam) 20%; Step 20%; Tala 20%; Music 20%."},{"Title":"Parichamuttu Kali (പരിചമുട്ട് കളി)","Source":"Arangu-2025 by-law p.20 (3. Parichamuttu Kali)","Sections":{"About":null,"TimeAndFormat":["Time: 10 minutes."],"Rules":["8 persons: 6 play and 2 sing. For boys only.","A traditional lamp is placed on the stage (the organisers give it).","Traditional costume: the mundu tucked up, red silk on the waist and on the head, hand ornaments and a cross chain are allowed, and a mundu about 5 fingers wide tied around the neck. Kruthavu is compulsory, with warrior make-up and a proper sword and shield.","Stories of saints, the church and Christian songs can be used. Adavu (moves) get more importance than steps.","If the sword or shield drops during the play, if the adavu or step is wrong, or if players collide, minus marks are given."],"Allowed":["Kuzhithalam (small elathalam) to keep the rhythm."],"NotAllowed":["Other musical instruments or recorded background."],"Judging":["Judging: Suitability of costume 20%; Step and adavu 30%; Tala 20%; Song 20%; Agility 10%."],"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Time: 10 minutes.\\n\\n## Rules\\n- 8 persons: 6 play and 2 sing. For boys only.\\n- A traditional lamp is placed on the stage (the organisers give it).\\n- Traditional costume: the mundu tucked up, red silk on the waist and on the head, hand ornaments and a cross chain are allowed, and a mundu about 5 fingers wide tied around the neck. Kruthavu is compulsory, with warrior make-up and a proper sword and shield.\\n- Stories of saints, the church and Christian songs can be used. Adavu (moves) get more importance than steps.\\n- If the sword or shield drops during the play, if the adavu or step is wrong, or if players collide, minus marks are given.\\n\\n## Allowed\\n- Kuzhithalam (small elathalam) to keep the rhythm.\\n\\n## Not allowed\\n- Other musical instruments or recorded background.\\n\\n## Judging\\n- Judging: Suitability of costume 20%; Step and adavu 30%; Tala 20%; Song 20%; Agility 10%."},{"Title":"Mime (മൈം)","Source":"Arangu-2025 by-law p.21 (4. Mime)","Sections":{"About":["A subject, idea or story is shown through body movements, facial expression, gestures and positions."],"TimeAndFormat":["Time: 10 minutes.","5 minutes are allowed for setting the scene."],"Rules":["The team has not less than 3 and not more than 12 persons.","Teams of young men and women together are allowed.","The team clears the stage after the competition.","The presentation must suit moral values. Insulting and mocking remarks must be avoided."],"Allowed":null,"NotAllowed":null,"Judging":["Judging: Idea 25%; Presentation 25%; Creativity 20%; Costume and make-up 15%; Music 15%."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- A subject, idea or story is shown through body movements, facial expression, gestures and positions.\\n\\n## Time and format\\n- Time: 10 minutes.\\n- 5 minutes are allowed for setting the scene.\\n\\n## Rules\\n- The team has not less than 3 and not more than 12 persons.\\n- Teams of young men and women together are allowed.\\n- The team clears the stage after the competition.\\n- The presentation must suit moral values. Insulting and mocking remarks must be avoided.\\n\\n## Judging\\n- Judging: Idea 25%; Presentation 25%; Creativity 20%; Costume and make-up 15%; Music 15%."},{"Title":"Chavittunatakam (ചവിട്ടുനാടകം)","Source":"Arangu-2025 by-law p.21-22 (5. Chavittunatakam)","Sections":{"About":["The subject is based on historical events.","It must have hand mudras (gestures), poetic quality and royal costumes. There are no separate marks for stage setting."],"TimeAndFormat":["Time: 30 minutes."],"Rules":null,"Allowed":["Recorded CD or pen drive for the background."],"NotAllowed":null,"Judging":["Judging: Step 40%; Acting 30%; Costume 20%; Song 10%."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- The subject is based on historical events.\\n- It must have hand mudras (gestures), poetic quality and royal costumes. There are no separate marks for stage setting.\\n\\n## Time and format\\n- Time: 30 minutes.\\n\\n## Allowed\\n- Recorded CD or pen drive for the background.\\n\\n## Judging\\n- Judging: Step 40%; Acting 30%; Costume 20%; Song 10%."},{"Title":"KCYM Anthem (കെ.സി.വൈ.എം ആന്തം)","Source":"Arangu-2025 by-law p.22 (6. KCYM Anthem)","Sections":{"About":["The KCYM state anthem is sung, as a marching tune."],"TimeAndFormat":null,"Rules":["The team has not less than 3 and not more than 7 members.","The team carries the official KCYM flag (the organisers give it).","The team has both young men and young women."],"Allowed":null,"NotAllowed":["Beating the rhythm while singing the anthem.","Seconds (second-voice singing) and repetition.","A mic."],"Judging":["Judging: Purity of pitch (shruti shuddhi) 20%; Tala 20%; Blending of voices (swarachercha) 20%; Clear pronunciation 20%; Expression (bhavam) 20%."],"Points":null,"Notes":["The by-law prints no time limit for the KCYM Anthem."]},"Markdown":"## About this competition\\n- The KCYM state anthem is sung, as a marching tune.\\n\\n## Rules\\n- The team has not less than 3 and not more than 7 members.\\n- The team carries the official KCYM flag (the organisers give it).\\n- The team has both young men and young women.\\n\\n## Not allowed\\n- Beating the rhythm while singing the anthem.\\n- Seconds (second-voice singing) and repetition.\\n- A mic.\\n\\n## Judging\\n- Judging: Purity of pitch (shruti shuddhi) 20%; Tala 20%; Blending of voices (swarachercha) 20%; Clear pronunciation 20%; Expression (bhavam) 20%.\\n\\n## Notes for participants\\n- The by-law prints no time limit for the KCYM Anthem."},{"Title":"Nadanpattu - Folk Song (നാടൻപാട്ട്)","Source":"Arangu-2025 by-law p.23 (7. Nadanpattu)","Sections":{"About":["The tradition of the song is told on the stage.","Only songs handed down by word of mouth are used. Ritual songs, festival songs, farming songs and play songs can be sung."],"TimeAndFormat":["Time: 10 minutes."],"Rules":["The team has not less than 3 and not more than 7 members.","KCYM members themselves play the local traditional instruments.","Costumes are not counted in the judging."],"Allowed":null,"NotAllowed":["Recorded background.","Electronic instruments, CD or karaoke.","A mic is not given."],"Judging":["Judging: Tala and melody 25%; Literature (lyrics) 20%; Pronunciation 20%; Harmony of the chorus 25%; Instrument 10%."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- The tradition of the song is told on the stage.\\n- Only songs handed down by word of mouth are used. Ritual songs, festival songs, farming songs and play songs can be sung.\\n\\n## Time and format\\n- Time: 10 minutes.\\n\\n## Rules\\n- The team has not less than 3 and not more than 7 members.\\n- KCYM members themselves play the local traditional instruments.\\n- Costumes are not counted in the judging.\\n\\n## Not allowed\\n- Recorded background.\\n- Electronic instruments, CD or karaoke.\\n- A mic is not given.\\n\\n## Judging\\n- Judging: Tala and melody 25%; Literature (lyrics) 20%; Pronunciation 20%; Harmony of the chorus 25%; Instrument 10%."},{"Title":"Ganamela - Orchestra Song (ഗാനമേള)","Source":"Arangu-2025 by-law p.24 (8. Ganamela)","Sections":{"About":null,"TimeAndFormat":["Time: 10 minutes at most."],"Rules":["The team has not less than 6 and not more than 8 members. 3 to 5 of them can handle the musical instruments.","At least 3 singers are in the team.","Sing at least 2 songs. Songs in other languages can also be included; other languages are not compulsory. One Malayalam song is compulsory.","The Ganamela must begin with a devotional song.","Solo, duet and group ways of singing can be used.","The musical instruments are played manually.","Instruments to use: 1) Keyboard. 2) Rhythm pad or composer, any one. 3) Lead guitar, acoustic guitar or bass guitar, any two."],"Allowed":null,"NotAllowed":["Recorded music and accompaniment on the keyboard."],"Judging":["Judging: Orchestra 35%; Purity of pitch (shruti shuddhi) 25%; Ability to sing together 20%; Tala 10%; Laya and bhava 10%."],"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Time: 10 minutes at most.\\n\\n## Rules\\n- The team has not less than 6 and not more than 8 members. 3 to 5 of them can handle the musical instruments.\\n- At least 3 singers are in the team.\\n- Sing at least 2 songs. Songs in other languages can also be included; other languages are not compulsory. One Malayalam song is compulsory.\\n- The Ganamela must begin with a devotional song.\\n- Solo, duet and group ways of singing can be used.\\n- The musical instruments are played manually.\\n- Instruments to use: 1) Keyboard. 2) Rhythm pad or composer, any one. 3) Lead guitar, acoustic guitar or bass guitar, any two.\\n\\n## Not allowed\\n- Recorded music and accompaniment on the keyboard.\\n\\n## Judging\\n- Judging: Orchestra 35%; Purity of pitch (shruti shuddhi) 25%; Ability to sing together 20%; Tala 10%; Laya and bhava 10%."},{"Title":"Debate (ഡിബേറ്റ്)","Source":"Arangu-2025 by-law p.25 (9. Debate)","Sections":{"About":["A team of 2 persons: one proposer and one opposer.","Each of them can use 5 minutes. The first 5 minutes are for the person who is for the topic, and the last 5 minutes for the person against it."],"TimeAndFormat":["Time: 10 minutes."],"Rules":["Debate contestants must not leave the hall or use a mobile phone until the competition is over.","Teams that do not follow the instructions of the diocesan committee are disqualified.","The contestants bring their own food, water and snacks."],"Allowed":null,"NotAllowed":null,"Judging":["Judging: Ability to speak without stage fright 20%; Correct language 15%; Clarity of ideas 25%; Gestures 15%; Suitable voice modulation 15%; Clear pronunciation 10%."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- A team of 2 persons: one proposer and one opposer.\\n- Each of them can use 5 minutes. The first 5 minutes are for the person who is for the topic, and the last 5 minutes for the person against it.\\n\\n## Time and format\\n- Time: 10 minutes.\\n\\n## Rules\\n- Debate contestants must not leave the hall or use a mobile phone until the competition is over.\\n- Teams that do not follow the instructions of the diocesan committee are disqualified.\\n- The contestants bring their own food, water and snacks.\\n\\n## Judging\\n- Judging: Ability to speak without stage fright 20%; Correct language 15%; Clarity of ideas 25%; Gestures 15%; Suitable voice modulation 15%; Clear pronunciation 10%."},{"Title":"Quiz (ക്വിസ്)","Source":"Arangu-2025 by-law p.26 (10. Quiz)","Sections":{"About":["A team has up to 3 members.","Reading portions: {{QuizPortions}}"],"TimeAndFormat":null,"Rules":null,"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":["The by-law prints no marking scheme and no time limit for the Quiz."]},"Markdown":"## About this competition\\n- A team has up to 3 members.\\n- Reading portions: {{QuizPortions}}\\n\\n## Notes for participants\\n- The by-law prints no marking scheme and no time limit for the Quiz."}]'),s=[],r=[{Key:"RegistrationStart",Kind:"date",Label:"Registration opens",Value:"2025-08-11",Source:"Arangu-2025 by-law p.3 rule 1.a and p.27 (Registration Starts: AUG 11, MON)"},{Key:"RegistrationDeadline",Kind:"date",Label:"Last date to register",Value:"2025-08-22, 10 pm",Source:"Arangu-2025 by-law p.3 rule 1.a (last date 22 August, 10 pm) and p.27 (AUG 22, FRI)"},{Key:"DebateQuizDate",Kind:"date",Label:"Debate and Quiz competitions",Value:"2025-08-24",Source:"Arangu-2025 by-law p.2 and p.27 (AUG 24, SUN)"},{Key:"KalolsavamDate",Kind:"date",Label:"Kalolsavam (all other competitions)",Value:"2025-09-13",Source:"Arangu-2025 by-law p.2 and p.27 (SEP 13, SAT)"},{Key:"Venue",Kind:"address",Label:"Event venue",Value:{Name:"Nirmala College",Address:"",City:"Muvattupuzha",MapUrl:"",Directions:"Each competition is in an auditorium, hall or classroom of the college."},Source:"Arangu-2025 by-law p.2 and p.9 rule 4.a"},{Key:"RegistrationFee",Kind:"fee",Label:"Registration fee",Value:"INR 1000 per unit",Source:"Arangu-2025 by-law p.3 rule 1.c"},{Key:"NoShowFine",Kind:"fee",Label:"Fine for registering a group item and not taking part",Value:"INR 100 per item, in addition to the registration fee",Source:"Arangu-2025 by-law p.4 rule 1.g"},{Key:"GreenRoomDeposit",Kind:"fee",Label:"Green room caution deposit",Value:"INR 1000 per unit that needs a green room",Source:"Arangu-2025 by-law p.9 rule 4.c"},{Key:"AppealFee",Kind:"fee",Label:"Appeal fee",Value:"INR 1000 per appeal",Source:"Arangu-2025 by-law p.11 rule 5.d"},{Key:"BirthDateRange",Kind:"text",Label:"Date of birth range for 15 to 30 years",Value:"Born between 1 May 1994 and 1 May 2010",Source:"Arangu-2025 by-law p.4 rule 1.h"},{Key:"QuizPortions",Kind:"text",Label:"Quiz reading portions",Value:"YOUCAT (10%): Part 1, Chapter 2 (questions 71 to 115). Christus Vivit, Christ Lives (10%): Chapter 4. Bible (35%): Judges 11 to 21; Sirach (Prabhashakan) 41 to 50; Luke 17 to 24; Ephesians 1 to 6. KCYM (45%): history, vision, working style, activities, state constitution and the study topic.",Source:"Arangu-2025 by-law p.26 (Quiz)"},{Key:"DioceseOfficeContact",Kind:"contact",Label:"KCYM Diocese office",Value:{Name:"KCYM Diocese Office, Kothamangalam",Role:"Office",Phone:"977 825 1858",WhatsApp:"",Email:""},Source:"Arangu-2025 by-law p.27 (MORE INFO)"},{Key:"PresidentContact",Kind:"contact",Label:"President",Value:{Name:"Savio Thottupuram",Role:"President",Phone:"828 171 6660",WhatsApp:"",Email:""},Source:"Arangu-2025 by-law p.27 (MORE INFO)"},{Key:"GeneralSecretaryContact",Kind:"contact",Label:"General Secretary",Value:{Name:"Anu Mekkuzhikattu",Role:"General Secretary",Phone:"9383429337",WhatsApp:"",Email:""},Source:"Arangu-2025 by-law p.27 (MORE INFO)"},{Key:"SecretaryContact",Kind:"contact",Label:"Secretary",Value:{Name:"Alphonsa Joy",Role:"Secretary",Phone:"859 088 6799",WhatsApp:"",Email:""},Source:"Arangu-2025 by-law p.27 (MORE INFO)"}],l=[{Claim:"Rules, criteria, fees, dates, appeals and awards for Arangu-2025.",SourceType:"Primary - organiser's own by-law",Source:"Arangu25-bylaw.pdf (Yuvadeepthi KCYM Kothamangalam Eparchy, Arangu-2025 Eparchy Kalolsavam by-law, 27 pages, Malayalam)",Url:""}],m={TemplateKey:e,Year:2025,Note:t,Page:n,ParticipantTypes:a,AgeGroups:o,Competitions:i,CompetitionAgeGroups:s,Variables:r,Evidence:l};export{o as AgeGroups,s as CompetitionAgeGroups,i as Competitions,l as Evidence,t as Note,n as Page,a as ParticipantTypes,e as TemplateKey,r as Variables,u as Year,m as default};
